ee:variables.ee:set-variable:
%dw 2.0
output application/java
var p = vars.currentRecord
---
if (isEmpty(p.erp_code default ""))
	{ code: "MISSING_ERP_CODE", message: "ERP product code is missing" }
else if (isEmpty(p.product_name default ""))
	{ code: "MISSING_PRODUCT_NAME", message: "Product name is missing" }
else if (p.unit_price == null)
	{ code: "MISSING_PRICE", message: "Unit price is missing" }
else if ((p.unit_price as Number default -1) < 0)
	{ code: "NEGATIVE_PRICE", message: "Unit price cannot be negative: " ++ (p.unit_price as String) }
else if (isEmpty(p.family default ""))
	{ code: "MISSING_FAMILY", message: "Product family is missing" }
else if (!(["Hardware", "Service", "Software"] contains p.family))
	{ code: "INVALID_FAMILY", message: "Invalid product family: " ++ (p.family as String) }
else if (isEmpty(p.uom default ""))
	{ code: "MISSING_UOM", message: "Unit of measure is missing" }
else
	{ code: "VALIDATION_FAILED", message: "Product record failed validation checks" }

salesforce:query.salesforce:parameters:
#[output application/java
---
{
	priceBookName: p('salesforce.priceBookName') default "ERP Catalog Price Book"
}]

salesforce:update.salesforce:records:
#[[{
	Id: payload[0].Id,
	UnitPrice: vars.currentRecord.unit_price as Number,
	IsActive: upper(vars.currentRecord.status default "ACTIVE") != "DISCONTINUED"
}]]

salesforce:create.salesforce:records:
#[[{
	Product2Id: vars.salesforceProductId,
	Pricebook2Id: vars.standardPriceBookId,
	UnitPrice: vars.currentRecord.unit_price as Number,
	IsActive: upper(vars.currentRecord.status default "ACTIVE") != "DISCONTINUED"
}]]

salesforce:update.salesforce:records:
#[[{
	Id: vars.pricebookEntryId,
	UnitPrice: vars.currentRecord.unit_price as Number,
	IsActive: upper(vars.currentRecord.status default "ACTIVE") != "DISCONTINUED"
}]]

salesforce:create.salesforce:records:
#[[{
	Product2Id: vars.salesforceProductId,
	Pricebook2Id: vars.customPriceBookId,
	UnitPrice: vars.currentRecord.unit_price as Number,
	IsActive: upper(vars.currentRecord.status default "ACTIVE") != "DISCONTINUED"
}]]
